const execError = $json.execution?.error || $json.trigger?.error || {};
const searchText = [
  execError.message,
  execError.description,
  execError.stack,
  JSON.stringify(execError),
].filter(Boolean).join(' ').toLowerCase();

const lastNode = ($json.execution?.lastNodeExecuted || '').toLowerCase();

let title = ' Problème détecté';
let simpleMessage = "Une erreur est survenue dans le workflow. La cause du problème n'a pas été identifiée. Il s'agit probablement d'un dysfonctionnement temporaire de l'agent. Réessayez simplement.";

const isWhatsappNode = lastNode.includes('whatsapp');
const isGeneratorNode = lastNode.includes('generate_scene') || lastNode.includes('compose_real_product') || lastNode.includes('prompt_references') || searchText.includes('generate_scene_pollinations') || searchText.includes('compose_real_product');
const isStartNode = lastNode.includes('choisir produit') || lastNode.includes('lire lien') || lastNode.includes('product_img') || lastNode.includes('contexte produit') || lastNode.includes('scraper');

const isZanimoApiNode = lastNode.includes("api z'animo") || lastNode.includes('api zanimo');
const isAccessRefused = searchText.includes('403') || searchText.includes('401') || searchText.includes('forbidden') || searchText.includes('unauthorized') || searchText.includes('accès refusé') || searchText.includes('access denied');

const isBrevoNode = lastNode.includes('brevo');
const isConnectionError = searchText.includes('econnrefused') || searchText.includes('etimedout') || searchText.includes('enotfound') || searchText.includes('timeout') || searchText.includes('network');

if (searchText.includes('whatsapp') || isWhatsappNode) {
  title = ' Problème WhatsApp';
  simpleMessage = "L'envoi du message WhatsApp a échoué. Vérifiez que WhatsApp est bien connecté (relancez le conteneur si besoin),vérifiez le dossier (output) pour consulter l'image. ";

} else if ((isZanimoApiNode || searchText.includes('zanimo')) && isAccessRefused) {
  title = " Problème d'accès à l'API Zanimo";
  simpleMessage = "L'accès à l'API Zanimo pour récupérer les nouveaux clients a été refusé (403/401). Vérifiez que la clé d'API ou les identifiants de connexion sont toujours valides.";

} else if (isBrevoNode && isConnectionError) {
  title = ' Problème de connexion Brevo';
  simpleMessage = "La connexion au service Brevo a échoué (timeout ou service injoignable). Vérifiez la connexion internet du serveur et la disponibilité de Brevo, puis réessayez.";

} else if (isBrevoNode) {
  title = " Problème d'envoi Brevo";
  simpleMessage = "L'envoi de l'email via Brevo a échoué. Vérifiez que la clé API Brevo est valide et que le template utilisé existe toujours.";

} else if (searchText.includes('gemini') || searchText.includes('malformed_function_call') || (searchText.includes('quota') && !searchText.includes('cloudflare') && !isGeneratorNode)) {
  title = ' Problème Gemini';
  simpleMessage = "(Gemini) n'a pas pu répondre à cause d'une limite d'utilisation atteinte. Réessayez plus tard ou demain.";

} else if (isGeneratorNode || searchText.includes('cloudflare') || searchText.includes("génération a échoué") || searchText.includes("chemin d'image") || searchText.includes('econnrefused') || searchText.includes('enotfound')) {
  title = " Problème de génération d'image";
  simpleMessage = "La création de l'image publicitaire a échoué. Le service de génération est indisponible ou une erreur est survenue dans le workflow. Veuillez réessayer .";

} else if (searchText.includes('404') || searchText.includes('url') || isStartNode) {
  title = ' Problème de lien';
  simpleMessage = "Une erreur de lien a bloqué le workflow . Vérifiez le lien de votre produit et Réessayez.";
}

return [{
  json: {
    title,
    simpleMessage
  }
}];

